    LongPacker packer = new LongPacker(byteCount);
    ArrayList<Long> preValues = new ArrayList<>();
    int count = 1;
    byte[] bb = new byte[count * byteCount];
    int idx = 0;
    for (int i = 0; i < count; i++) {
        long[] vs = new long[8];
