    c1.addHead("a", "b", "c123");
    c1.addTail("a", "12", "c");
    c1.addTail("1284736", "b", "c");
    StringContainer c2 = new StringContainer(TsFileConstant.PATH_SEPARATOR);
    c2.addHead("a", "b", "c123");
    c2.addTail("a", "12", "c");
    c2.addTail("1284736", "b", "c");
